npx tsx -e '
import { parse, stringify, TokenData } from "./src/index.ts";

// Test case from STRINGIFY_TESTS: param followed by astral ID_Continue
const data = new TokenData([
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1D6FC}" },
]);
const result = stringify(data);
const expected = "/:\"test\"\u{1D6FC}";
console.log("Result:  ", JSON.stringify(result));
console.log("Expected:", JSON.stringify(expected));
console.log("Match:", result === expected);

// Also test wildcard case
const data2 = new TokenData([
  { type: "text", value: "/" },
  { type: "wildcard", name: "test" },
  { type: "text", value: "\u{1D6FC}" },
]);
const result2 = stringify(data2);
const expected2 = "/*\"test\"\u{1D6FC}";
console.log("\nWildcard Result:  ", JSON.stringify(result2));
console.log("Wildcard Expected:", JSON.stringify(expected2));
console.log("Match:", result2 === expected2);

// Verify the non-ID_Continue case stays unquoted
const data3 = new TokenData([
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1F600}" },
]);
const result3 = stringify(data3);
const expected3 = "/:test\u{1F600}";
console.log("\nNon-ID_Continue Result:  ", JSON.stringify(result3));
console.log("Non-ID_Continue Expected:", JSON.stringify(expected3));
console.log("Match:", result3 === expected3);
'

